/* @lc app=leetcode id=2963 lang=kotlin */ class Solution { fun numberOfGoodPartitions(nums: IntArray): Int = mutableMapOf<Int, Int>().let { last -> nums.indices.forEach { i -> last[nums[i]] = i }.let { nums.indices.fold(0 to 0) { (maxLast, count), i -> maxOf(maxLast, last[nums[i]]!!).let { newMax -> newMax to (if (i == newMax) count + 1 else count) } }.second.let { c -> (0 until c - 1).fold(1) { acc, _ -> (acc * 2) % 1000000007 } } } } }